∀ (T : ℕ) (v : ℝ) (hvFamily : v = CausalSmith.Stat.PomdpBinaryhiddenRate.vT T ∨ v = -CausalSmith.Stat.PomdpBinaryhiddenRate.vT T) (hv : |v| ≤ 1 / 16),
  have M := CausalSmith.Stat.PomdpBinaryhiddenRate.testingExperiment T v hvFamily hv;
  CausalSmith.Stat.PomdpBinaryhiddenRate.PomdpKernelLaw M ∧ CausalSmith.Stat.PomdpBinaryhiddenRate.SequentialIgnorability M ∧ CausalSmith.Stat.PomdpBinaryhiddenRate.StationaryStart M
